-- ============================================================
-- Flyway V10: anh/brand/rating cho san pham + catalog dien tu that.
-- Nguon data: DummyJSON (https://dummyjson.com) - dataset demo cong khai, anh CDN.
-- Gia quy doi USD -> VND (x25000), lam tron nghin. Sinh tu scripts/gen-seed.mjs.
-- ============================================================

ALTER TABLE products ADD COLUMN image_url VARCHAR(512);
ALTER TABLE products ADD COLUMN brand     VARCHAR(128);
ALTER TABLE products ADD COLUMN rating    NUMERIC(3, 2);

-- Chuan hoa ten category (them dau) + bo sung nhom dien tu
UPDATE categories SET name = 'Điện thoại' WHERE id = 1;
UPDATE categories SET name = 'Sách'       WHERE id = 3;

-- Backfill 4 san pham seed cu
UPDATE products SET brand = 'Apple',   rating = 4.7, image_url = 'https://cdn.dummyjson.com/product-images/smartphones/iphone-5s/thumbnail.webp'  WHERE id = 1;
UPDATE products SET brand = 'Samsung', rating = 4.5, image_url = 'https://cdn.dummyjson.com/product-images/smartphones/samsung-galaxy-s7/thumbnail.webp' WHERE id = 2;
UPDATE products SET brand = 'Apple',   rating = 4.8, image_url = 'https://cdn.dummyjson.com/product-images/laptops/apple-macbook-pro-14-inch-space-grey/thumbnail.webp'     WHERE id = 3;

-- Catalog dien tu (48 san pham)

-- Day sequence len qua id chen tay
SELECT setval(pg_get_serial_sequence('categories', 'id'), (SELECT MAX(id) FROM categories));
SELECT setval(pg_get_serial_sequence('products', 'id'),   (SELECT MAX(id) FROM products));
